WHERE f.tenant_id = #{tenantId} AND f.deleted_at IS NULL AND f.resource_id = #{query.resourceId}
AND v.version_no = #{query.versionNo}
AND f.outcome = #{query.outcome}
AND f.explicit_score IS NOT NULL
AND f.explicit_score IS NULL AND f.judge_score IS NOT NULL
AND f.explicit_score IS NULL AND f.judge_score IS NULL
