mapper.select:

WHERE f.tenant_id = #{tenantId} AND f.deleted_at IS NULL
  AND f.id IN #{id}
ORDER BY f.id

SELECT 
FROM ddc_ai_usage_feedback f
WHERE f.tenant_id = #{tenantId} AND f.deleted_at IS NULL
  AND f.resource_id IN #{r}
  AND f.explicit_score IS NULL AND f.judge_attempts < #{maxAttempts}
  AND (f.judge_state = 'PENDING' OR (f.judge_state = 'JUDGING' AND f.judge_lease_until < #{now}))
ORDER BY f.occurred_at, f.id
LIMIT #{limit}
FOR UPDATE


WHERE f.tenant_id = #{tenantId} AND f.deleted_at IS NULL
  AND f.resource_id = #{resourceId} AND f.version_id = #{versionId}
  AND f.occurred_at >= #{windowStart} AND f.occurred_at < #{windowEnd}
  AND COALESCE(f.explicit_score, f.judge_score) IS NOT NULL
ORDER BY COALESCE(f.explicit_score, f.judge_score) ASC, f.occurred_at DESC, f.id DESC
LIMIT #{limit}

SELECT f.id
FROM ddc_ai_usage_feedback f
WHERE f.tenant_id = #{tenantId} AND f.deleted_at IS NULL AND f.occurred_at < #{before}
ORDER BY f.id
LIMIT #{limit}
FOR UPDATE
